observation_step='      - name: Original five cases with bounded app-only observation\n        env:\n          OBSERVE_PLATFORM: \'${{ matrix.platform }}\'\n        run: |\n          python3 - <<\'PY\'\n          import datetime as dt, json, os, plistlib, re, subprocess, sys, threading\n          from pathlib import Path\n          assert os.environ.get(\'GITHUB_ACTIONS\') == \'true\'\n          platform = os.environ[\'OBSERVE_PLATFORM\']\n          out = Path(\'build/apple-observe\') / platform\n          out.mkdir(parents=True, exist_ok=False)\n          evidence = Path(\'build/team24-apple\') / platform / \'evidence\'\n          report = {\'source\':os.environ[\'GITHUB_SHA\'],\'run\':os.environ[\'GITHUB_RUN_ID\'],\'attempt\':os.environ[\'GITHUB_RUN_ATTEMPT\'],\'platform\':platform,\'errors\':[],\'scope\':\'redacted app/test metadata only; no extra AX or launch\'}\n          def save(name, value):\n              (out/name).write_text(json.dumps(value,indent=2)+\'\\n\')\n          def command(argv, timeout=20):\n              try:\n                  r=subprocess.run(argv,capture_output=True,text=True,timeout=timeout)\n                  return r.returncode,r.stdout\n              except Exception as e:\n                  report[\'errors\'].append({\'operation\':argv[:3],\'exception\':type(e).__name__})\n                  return -1,\'\'\n          def utc():return dt.datetime.now(dt.timezone.utc).isoformat()\n          code,version=command([\'xcodebuild\',\'-version\'])\n          report[\'xcode_version\']=version.strip() if code==0 else None\n          code,raw=command([\'xcrun\',\'simctl\',\'list\',\'devices\',\'available\',\'--json\'],60)\n          udid=None\n          if code==0:\n              try:\n                  data=json.loads(raw); prefix=\'iPhone\' if platform==\'iphone\' else \'iPad\'\n                  runtime,name,udid=max((runtime,d[\'name\'],d[\'udid\']) for runtime,values in data[\'devices\'].items() for d in values if d.get(\'isAvailable\') and d[\'name\'].startswith(prefix))\n                  report[\'selected_before_runner\']={\'runtime\':runtime,\'device\':name,\'udid\':udid}\n              except Exception as e:report[\'errors\'].append({\'operation\':\'device-selection\',\'exception\':type(e).__name__})\n          else:report[\'errors\'].append({\'operation\':\'device-selection\',\'exit\':code})\n          stop=threading.Event(); samples=[]; window={}\n          def observe_body():\n              active=False\n              for _ in range(1320):\n                  if stop.wait(5):return\n                  if not (evidence/\'wave3-native-ui.log\').exists():continue\n                  if not active:active=True;window[\'start_utc\']=utc()\n                  if len(samples)>=300:report[\'sampling_capped\']=True;return\n                  code,text=command([\'ps\',\'-axo\',\'pid=,ppid=,stat=,etime=,comm=\'],15)\n                  rows=[]\n                  if code:report[\'errors\'].append({\'operation\':\'process-snapshot\',\'exit\':code})\n                  else:\n                      for line in text.splitlines():\n                          fields=line.strip().split(None,4)\n                          if len(fields)!=5:continue\n                          pid,ppid,state,elapsed,executable=fields; base=Path(executable).name\n                          if not base.startswith(\'EXReaderHost\') or not pid.isdigit() or not ppid.isdigit():continue\n                          rows.append({\'pid\':int(pid),\'ppid\':int(ppid),\'state\':state,\'elapsed\':elapsed,\'name\':base})\n                  samples.append({\'utc\':utc(),\'processes\':rows});save(\'process-timeline.json\',samples)\n          def observe():\n              try:observe_body()\n              except Exception as e:report[\'errors\'].append({\'operation\':\'observer-thread\',\'exception\':type(e).__name__})\n          watcher=threading.Thread(target=observe,daemon=True)\n          report[\'runner_started_utc\']=utc();watcher.start();rc=125\n          try:\n              rc=subprocess.call([sys.executable,\'tests/apple_features_repair_20261029/focused_runner.py\',\'--platform\',platform])\n          finally:\n              report[\'runner_exit\']=rc;report[\'runner_ended_utc\']=utc()\n              stop.set();watcher.join(20);window[\'end_utc\']=utc();report[\'window\']=window\n              if watcher.is_alive():report[\'errors\'].append({\'operation\':\'observer-thread-not-stopped\'})\n              save(\'process-timeline.json\',samples)\n              try:\n                  result=json.loads((evidence/\'result.json\').read_text())\n                  report[\'runner_identity\']={k:result.get(k) for k in (\'source_sha\',\'run_id\',\'attempt\',\'platform\',\'destination\',\'accepted\')}\n                  dest=result.get(\'destination\',{})\n                  report[\'selected_matches_runner\']=isinstance(dest,dict) and dest.get(\'udid\')==udid and (result.get(\'source_sha\'),str(result.get(\'run_id\')),str(result.get(\'attempt\'))) == (report[\'source\'],report[\'run\'],report[\'attempt\'])\n                  if not report[\'selected_matches_runner\']:report[\'errors\'].append({\'operation\':\'device-identity-mismatch\'})\n              except Exception as e:report[\'errors\'].append({\'operation\':\'runner-result\',\'exception\':type(e).__name__})\n              if udid:\n                  code,container=command([\'xcrun\',\'simctl\',\'get_app_container\',udid,\'org.exreader.host\',\'app\'])\n                  report[\'installed_container_query_exit\']=code\n                  if code==0:\n                      try:\n                          info=plistlib.loads((Path(container.strip())/\'Info.plist\').read_bytes())\n                          report[\'installed_identity\']={k:info.get(k) for k in (\'CFBundleIdentifier\',\'CFBundleExecutable\',\'CFBundleShortVersionString\',\'EXRSourceSHA\')}\n                          built=plistlib.loads((Path(\'build/team24-apple\')/platform/\'derived-wave3/Build/Products/Debug-iphonesimulator/EXReaderHost.app/Info.plist\').read_bytes())\n                          report[\'built_identity\']={k:built.get(k) for k in report[\'installed_identity\']}\n                          if report[\'installed_identity\']!=report[\'built_identity\']:report[\'errors\'].append({\'operation\':\'installed-built-identity-mismatch\'})\n                          if info.get(\'CFBundleIdentifier\')!=\'org.exreader.host\' or info.get(\'EXRSourceSHA\')!=report[\'source\']:report[\'errors\'].append({\'operation\':\'installed-identity-mismatch\'})\n                      except Exception as e:report[\'errors\'].append({\'operation\':\'installed-plist\',\'exception\':type(e).__name__})\n                  else:report[\'errors\'].append({\'operation\':\'installed-container\',\'exit\':code})\n              classes=(\'background assertion\',\'Timed out\',\'terminate\',\'termination\',\'launch\',\'crash\',\'denied\')\n              if udid and window.get(\'start_utc\'):\n                  begin=dt.datetime.fromisoformat(window[\'start_utc\']).strftime(\'%Y-%m-%d %H:%M:%S%z\')\n                  end=dt.datetime.fromisoformat(window[\'end_utc\']).strftime(\'%Y-%m-%d %H:%M:%S%z\')\n                  predicate=\'(process BEGINSWITH "EXReaderHost") OR ((process == "runningboardd" OR process == "SpringBoard" OR process == "testmanagerd") AND eventMessage CONTAINS "org.exreader.host")\'\n                  code,raw=command([\'xcrun\',\'simctl\',\'spawn\',udid,\'log\',\'show\',\'--start\',begin,\'--end\',end,\'--style\',\'ndjson\',\'--predicate\',predicate],60)\n                  report[\'app_window_log_exit\']=code;rows=[]\n                  if code==0:\n                      for line in raw.splitlines():\n                          try:item=json.loads(line)\n                          except ValueError:continue\n                          message=str(item.get(\'eventMessage\',\'\'));labels=[x for x in classes if x.lower() in message.lower()]\n                          if not labels:continue\n                          rows.append({\'timestamp\':item.get(\'timestamp\'),\'pid\':item.get(\'processID\'),\'process\':Path(str(item.get(\'processImagePath\',\'\'))).name,\'classes\':labels,\'numeric_error_codes\':re.findall(r\'(?:Code|code|errno)[=: ]+(-?\\d+)\',message)[:8]})\n                          if len(rows)==1000:report[\'app_window_log_capped\']=True;break\n                  else:report[\'errors\'].append({\'operation\':\'app-window-log\',\'exit\':code})\n                  save(\'app-window-log-redacted.json\',rows)\n              crashes=[]\n              if window.get(\'start_utc\'):\n                  start=dt.datetime.fromisoformat(window[\'start_utc\']).timestamp();finish=dt.datetime.fromisoformat(window[\'end_utc\']).timestamp()\n                  roots=[Path.home()/\'Library/Logs/DiagnosticReports\']\n                  if udid:roots.append(Path.home()/\'Library/Developer/CoreSimulator/Devices\'/udid/\'data/Library/Logs/CrashReporter\')\n                  for root in roots:\n                      for path in sorted(root.glob(\'EXReaderHost*.ips\')):\n                          if len(crashes)>=20:report[\'crash_summary_capped\']=True;break\n                          try:\n                              if not start<=path.stat().st_mtime<=finish+5:continue\n                              if path.stat().st_size>8*1024*1024:report[\'errors\'].append({\'operation\':\'crash-size-cap\'});continue\n                              text=path.read_text(errors=\'replace\');decoder=json.JSONDecoder();first,offset=decoder.raw_decode(text)\n                              rest=text[offset:].lstrip();body=decoder.raw_decode(rest)[0] if rest else first\n                              proc=body.get(\'procName\',first.get(\'app_name\',\'\'))\n                              if not str(proc).startswith(\'EXReaderHost\'):continue\n                              termination=body.get(\'termination\',{});exception=body.get(\'exception\',{})\n                              crashes.append({\'process\':proc,\'pid\':body.get(\'pid\'),\'timestamp\':body.get(\'captureTime\',first.get(\'timestamp\')),\'exception_type\':exception.get(\'type\'),\'signal\':exception.get(\'signal\'),\'termination_namespace\':termination.get(\'namespace\'),\'termination_code\':termination.get(\'code\')})\n                          except Exception as e:report[\'errors\'].append({\'operation\':\'crash-summary\',\'exception\':type(e).__name__})\n              save(\'crash-summaries.json\',crashes);timeline=[];log=evidence/\'wave3-native-ui.log\'\n              if log.exists():\n                  with log.open(errors=\'replace\') as stream:\n                      for number,line in enumerate(stream,1):\n                          action=None\n                          for label in (\'Test Case\',\'Start Test\',\'Set Up\',\'Tear Down\',\'Terminate\',\'Launch\',\'Find\',\'Check existence\',\'Tap\',\'Type\',\'snapshot-tap-frame\',\'Exceeded execution time\',\'background assertion\',\'Restarting after\'):\n                              if label.lower() in line.lower():action=label;break\n                          if action is None:continue\n                          elapsed=re.search(r\'t\\s*=\\s*([0-9.]+)s\',line)\n                          row={\'line\':number,\'action\':action,\'elapsed_s\':float(elapsed.group(1)) if elapsed else None,\'cases\':re.findall(r\'test[A-Z][A-Za-z0-9_]+\',line),\'feature_ids\':re.findall(r\'features\\.[A-Za-z0-9_.-]+\',line)}\n                          if \'snapshot-tap-frame\' in line:row[\'frame_numbers\']=re.findall(r\'-?\\d+(?:\\.\\d+)?\',line.split(\'snapshot-tap-frame\',1)[1])[:20]\n                          timeline.append(row)\n                          if len(timeline)==20000:report[\'errors\'].append({\'operation\':\'ui-timeline-cap\'});break\n              else:report[\'errors\'].append({\'operation\':\'missing-ui-log\'})\n              save(\'ui-timeline-redacted.json\',timeline)\n              bundle=evidence/\'wave3.xcresult\'\n              if bundle.exists():\n                  code,raw=command([\'xcrun\',\'xcresulttool\',\'get\',\'test-results\',\'summary\',\'--path\',str(bundle),\'--format\',\'json\'],120)\n                  report[\'xcresult_summary_exit\']=code\n                  if code==0:\n                      try:\n                          summary=json.loads(raw)\n                          report[\'test_totals\']={k:summary.get(k) for k in (\'totalTestCount\',\'passedTests\',\'failedTests\',\'skippedTests\',\'finishTime\',\'startTime\',\'result\')}\n                      except ValueError:report[\'errors\'].append({\'operation\':\'xcresult-summary-json\'})\n                  else:report[\'errors\'].append({\'operation\':\'xcresult-summary\',\'exit\':code})\n              else:report[\'errors\'].append({\'operation\':\'missing-xcresult\'})\n              report[\'complete\']=not report[\'errors\'] and not any(report.get(k) for k in (\'sampling_capped\',\'app_window_log_capped\',\'crash_summary_capped\')) and bool(samples) and bool(timeline) and report.get(\'selected_matches_runner\',False)\n              save(\'receipt.json\',report);print(json.dumps(report),flush=True)\n          sys.exit(rc if rc else (0 if report[\'complete\'] else 3))\n          \n          PY\n      - name: Preserve bounded observation even when original tests fail\n        if: always()\n        uses: actions/upload-artifact@v4\n        with:\n          name: apple-observe-${{ matrix.platform }}-${{ github.run_id }}-${{ github.run_attempt }}\n          path: build/apple-observe/${{ matrix.platform }}/\n          retention-days: 30\n          if-no-files-found: error\n'
